#!/usr/bin/env node
/**
 * Execute all ref/prompts/* audit prompts for StackPractices
 * and write the requested output files to ref/.
 *
 * Data source: ref/audit-data.json (generated by forensic-data-generator.cjs)
 */

const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const REF = path.join(ROOT, 'ref');
const OUT = REF; // all prompt outputs go to ref/

function loadJson(name) {
  return JSON.parse(fs.readFileSync(path.join(REF, name), 'utf8'));
}

function ensureDir(dir) {
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
}

function csv(rows, columns) {
  const lines = [columns.join(',')];
  for (const r of rows) {
    lines.push(columns.map(c => {
      const v = r[c] ?? '';
      const s = String(v).replace(/"/g, '""');
      if (s.includes(',') || s.includes('\n') || s.includes('"')) return `"${s}"`;
      return s;
    }).join(','));
  }
  return lines.join('\n');
}

function mdTable(rows, columns, labels) {
  if (rows.length === 0) return '_No data._';
  const header = '| ' + labels.join(' | ') + ' |';
  const sep = '|' + labels.map(() => ' --- |').join('');
  const body = rows.map(r => '| ' + columns.map(c => String(r[c] ?? '').replace(/\n/g, ' ').replace(/\|/g, '\\|')).join(' | ') + ' |');
  return [header, sep, ...body].join('\n');
}

function escapeMd(text) {
  return String(text).replace(/\|/g, '\\|').replace(/\n/g, ' ');
}

function severityClass(sev) {
  if (sev >= 90) return 'Critical';
  if (sev >= 70) return 'High';
  if (sev >= 40) return 'Medium';
  return 'Low';
}

// ----------------------------- DATA LOADING -----------------------------
const data = loadJson('audit-data.json');
const internals = data.internals || {};
const issues = data.issues || {};
const content = data.content || {};
const summary = data.summary || {};
const pages = data.pages || [];
const mdFiles = data.mdFiles || [];
const sitemap = data.sitemap || [];
const robots = data.robots || {};

const enMd = mdFiles.filter(m => !m.isEs);
const esMd = mdFiles.filter(m => m.isEs);

const detailPagePaths = new Set(enMd.map(m => `/${m.contentType}/${m.slug}/`));
const listingPagePaths = new Set(['/recipes/', '/patterns/', '/docs/', '/guides/', '/tags/', '/topics/']);
const tagPagePaths = new Set(pages.filter(p => p.path.startsWith('/tags/') && p.path !== '/tags/').map(p => p.path));
const esTagPagePaths = new Set(pages.filter(p => p.path.startsWith('/es/tags/') && p.path !== '/es/tags/').map(p => p.path));

const distDetailPages = pages.filter(p => detailPagePaths.has(p.path));
const distListingPages = pages.filter(p => listingPagePaths.has(p.path) || p.path === '/' || p.path === '/es/');
const distTagPages = pages.filter(p => tagPagePaths.has(p.path) || esTagPagePaths.has(p.path));

const contentThinPages = enMd.filter(m => m.lineCount < 300 || m.wordCount < 300).map(m => ({
  url: `https://stackpractices.com/${m.contentType}/${m.slug}/`,
  file: m.file,
  lines: m.lineCount,
  words: m.wordCount,
}));

const contentDescTooLong = distDetailPages.filter(p => p.metaDesc && p.metaDesc.length > 160).length;
const listingDescTooLong = distListingPages.filter(p => p.metaDesc && p.metaDesc.length > 160).length;
const tagDescTooLong = distTagPages.filter(p => p.metaDesc && p.metaDesc.length > 160).length;

const canonicalMismatchDetail = issues.canonicalMismatch || [];

const missingExpectedHreflang = pages.filter(p => {
  if (p.path === '/404/' || p.path === '/es/404/' || p.path === '/search/' || p.path === '/es/search/') return false;
  return p.hreflang.length === 0;
});

const orphanLegal = pages.filter(p => ['editorial-policy', 'affiliate-disclosure', 'legal-notice'].some(x => p.path.includes(x)));

// Helper to build a paginated sample table
function sampleTable(arr, columns, labels, limit = 50) {
  return mdTable(arr.slice(0, limit), columns, labels);
}

